_static_list_cargo_message_format() {
    cat <<-'ARGCEOF'
	human	Render diagnostics in the default human-readable format
	short	Alias for human
	json	Emit JSON messages to stdout
	json-diagnostic-short	Ensure the rendered field of JSON messages contains the "short" rendering from rustc
	json-diagnostic-rendered-ansi	Ensure the rendered field of JSON messages contains ANSI color codes
	json-render-diagnostics	Output JSON messages with human-readable diagnostics
ARGCEOF
}

_static_list_run_ignored() {
    cat <<-'ARGCEOF'
	default	Run non-ignored tests
	only	Run ignored tests
	all	Run both ignored and non-ignored tests
ARGCEOF
}

_static_list_message_format() {
    cat <<-'ARGCEOF'
	auto	Auto-detect: human if stdout is an interactive terminal, oneline otherwise
	human	A human-readable output format
	oneline	One test per line
	json	JSON with no whitespace
	json-pretty	JSON, prettified
ARGCEOF
}

